int result = 0;
for (int x : nums) result ^= x;
return result;

// --- Count set bits ---
int count = 0;
while (n) { n &= n - 1; count++; }   // clears the lowest set bit
return count;
// or just __builtin_popcount(n), which compiles to one instruction

// --- Counting Bits as a DP ---
vector<int> dp(n + 1, 0);
for (int i = 1; i <= n; i++)
    dp[i] = dp[i >> 1] + (i & 1);

// --- Add without + ---
// Use UNSIGNED for the shift: signed overflow is undefined behaviour.
int add(int a, int b) {
    while (b != 0) {
        unsigned carry = (unsigned)(a & b) << 1;
        a = a ^ b;
        b = (int)carry;
    }
    return a;
}

// --- Reverse 32 bits ---
uint32_t reverseBits(uint32_t n) {
    uint32_t out = 0;
    for (int i = 0; i < 32; i++) {
        out = (out << 1) | (n & 1);   // shift the answer, append n's last bit
        n >>= 1;
    }
    return out;
}

// --- Isolate the lowest set bit ---
int lowest = n & -n;

