// --- XOR: pairs cancel ---
let result = 0;
for (const x of nums) result ^= x;
return result;

// --- Count set bits ---
let count = 0;
while (n) { n &= n - 1; count++; }   // clears the lowest set bit
return count;

// --- Counting Bits as a DP ---
const dp = new Array(n + 1).fill(0);
for (let i = 1; i <= n; i++)
  dp[i] = dp[i >> 1] + (i & 1);

// --- Add without + ---
// JS bitwise ops already coerce to 32-bit SIGNED, so this wraps like Java.
const add = (a, b) => {
  while (b !== 0) {
    const carry = (a & b) << 1;
    a = a ^ b;
    b = carry;
  }
  return a;
};

// --- Reverse 32 bits ---
const reverseBits = (n) => {
  let out = 0;
  for (let i = 0; i < 32; i++) {
    out = (out << 1) | (n & 1);
    n >>>= 1;          // UNSIGNED shift — >> sign-extends and loops forever
  }
  return out >>> 0;    // coerce the result back to unsigned for display
};

// --- Isolate the lowest set bit ---
const lowest = n & -n;

